import { Ticket, Event, EventParams } from './types.js';
import {
  Spec,
  AssembledTransaction,
  Client as ContractClient,
  ClientOptions as ContractClientOptions,
  MethodOptions,
} from '@stellar/stellar-sdk/contract';
import { Address } from '@stellar/stellar-sdk';

export interface Client {
  verify_ticket(
    { ticket_id }: { ticket_id: bigint },
    options?: MethodOptions,
  ): Promise<AssembledTransaction<Ticket>>;
  get_event(
    { event_id }: { event_id: bigint },
    options?: MethodOptions,
  ): Promise<AssembledTransaction<Event>>;
  create_event(
    {
      organizer,
      event_id,
      params,
    }: { organizer: string | Address; event_id: bigint; params: EventParams },
    options?: MethodOptions,
  ): Promise<AssembledTransaction<void>>;
  issue_ticket(
    {
      organizer,
      event_id,
      to,
      tier,
      seat,
      price,
    }: {
      organizer: string | Address;
      event_id: bigint;
      to: string | Address;
      tier: string;
      seat: string;
      price: bigint;
    },
    options?: MethodOptions,
  ): Promise<AssembledTransaction<bigint>>;
  purchase_primary(
    {
      buyer,
      event_id,
      tier,
      seat,
    }: {
      buyer: string | Address;
      event_id: bigint;
      tier: string;
      seat: string;
    },
    options?: MethodOptions,
  ): Promise<AssembledTransaction<bigint>>;
  transfer_ticket(
    {
      from,
      ticket_id,
      to,
    }: { from: string | Address; ticket_id: bigint; to: string | Address },
    options?: MethodOptions,
  ): Promise<AssembledTransaction<void>>;
  check_in(
    {
      organizer,
      ticket_id,
    }: { organizer: string | Address; ticket_id: bigint },
    options?: MethodOptions,
  ): Promise<AssembledTransaction<void>>;
  revoke_ticket(
    {
      organizer,
      ticket_id,
    }: { organizer: string | Address; ticket_id: bigint },
    options?: MethodOptions,
  ): Promise<AssembledTransaction<void>>;
  revoke_batch(
    {
      organizer,
      ticket_ids,
    }: { organizer: string | Address; ticket_ids: Array<bigint> },
    options?: MethodOptions,
  ): Promise<AssembledTransaction<void>>;
  list_for_resale(
    {
      owner,
      ticket_id,
      price,
    }: { owner: string | Address; ticket_id: bigint; price: bigint },
    options?: MethodOptions,
  ): Promise<AssembledTransaction<void>>;
  cancel_resale(
    { owner, ticket_id }: { owner: string | Address; ticket_id: bigint },
    options?: MethodOptions,
  ): Promise<AssembledTransaction<void>>;
  buy_resale(
    { buyer, ticket_id }: { buyer: string | Address; ticket_id: bigint },
    options?: MethodOptions,
  ): Promise<AssembledTransaction<void>>;
}

